#include "compute.h"
#include <stdio.h>
#include <string.h>
int compute(int input, char* out, int outLen) {
  char tmp[64];
  int v = input * 2;
  int n = snprintf(tmp, sizeof(tmp), "value=%d", v);
  if (n + 1 > outLen) return -1;
  memcpy(out, tmp, n + 1);
  return n;
}
